def main():
    inp,out=map(Path,sys.argv[1:3]);request=json.loads(inp.read_text());corepath=inp.parent/request['core_json'];core=json.loads(corepath.read_text());positivepath=inp.parent/request['positive_json'];positive=json.loads(positivepath.read_text());case=core['case'];p=core['parameters'];start=time.monotonic()
    if positive['stage']!='event_lepton':raise ValueError('Require fully committed positive-event checkpoint')
    path=inp.parent/p['native_body_cache']
    if hashlib.sha256(path.read_bytes()).hexdigest()!=p['native_body_cache_sha256']:raise ValueError('Pinned native BODY mismatch')
    body=load_body(path);model=from_body(body,p);base=model['base'];field=model['field'];rotor=base['rotor'];nr=rotor['dimension'];corestates=np.load(inp.parent/request['core_npz']);posstates=np.load(inp.parent/request['positive_npz']);name='antilepton';initial=corestates[name+'_raw_normalized_source'];h=assemble(model,name);off=assemble(model,name,coupled=False);hopoff=no_hop_law(model,name,h);engine=AllM(model,name,h);offengine=AllM(model,name,off);hopengine=AllM(model,name,hopoff);curr=[assemble(model,name,derivative=(mu,)) for mu in range(6)];nm=base['operators'][name]['Q'].shape[0];nf=len(base['scalar']['grid']);kicked=field_action(initial,nm,nf,nr,expm(1j*case['kick']*(field['Pi'][2]+.37*field['Pi'][4])));phase=mean(initial,h);labels,effects=native_charge_receiver(model,name);before=measurements(model,name,initial);after=measurements(model,name,kicked);records=[];xs=[];bs=[];receivers=[]
    for t in case['times']:
        b=engine.evolve(initial,t,phase);x=engine.evolve(kicked,t,phase);bm=measurements(model,name,b);xm=measurements(model,name,x);joint=joint_receiver(x,effects,base['scalar'],rotor,field);records.append(dict(time=t,norm=norm(x)**2,excess={key:xm[key]-bm[key] for key in bm},current_excess=[mean(x,a)-mean(b,a) for a in curr],joint_probability_sum=float(joint.sum()),joint=joint.tolist()));xs.append(x);bs.append(b);receivers.append(joint)
    last=case['times'][-1];fb=offengine.evolve(initial,last,phase);fx=offengine.evolve(kicked,last,phase);fbm=measurements(model,name,fb);fxm=measurements(model,name,fx);hb=hopengine.evolve(initial,last,phase);hx=hopengine.evolve(kicked,last,phase);rho=observable(model,name,matter=base['operators'][name]['rho0']);routes=[assemble(model,name,route_derivative=edge) for edge in range(2)];graph=1j*(h@(rho@initial)-rho@(h@initial))+sum((a@initial for a in routes),np.zeros_like(initial));k=np.array(case['wavevector']);rhok=density(model,name,k);local=[spatial_current(model,name,k,a) for a in range(3)];wrong=[spatial_current(model,name,k,a,include_mechanical=False) for a in range(3)];change=1j*(h@(rhok@initial)-rhok@(h@initial));ward=change+1j*sum((q*(a@initial) for q,a in zip(k,local)),np.zeros_like(initial));bad=change+1j*sum((q*(a@initial) for q,a in zip(k,wrong)),np.zeros_like(initial));momentum=observable(model,name,rq=np.kron(np.eye(nr),field['Pi'][2]));electric=observable(model,name,rq=np.kron(np.eye(nr),field['H_E']));force=1j*(h@(momentum@initial)-momentum@(h@initial));bare=1j*(electric@(momentum@initial)-momentum@(electric@initial));q0=np.array([mean(initial,observable(model,name,matter=a)) for a in effects]);qb=np.array([mean(hb,observable(model,name,matter=a)) for a in effects]);qx=np.array([mean(hx,observable(model,name,matter=a)) for a in effects]);c=native_C(model,'lepton');pi=posstates['lepton_initial'];pk=posstates['lepton_kicked'];px=posstates['lepton_event'];pb=posstates['lepton_baseline'];alignment=np.vdot(initial,c@pi);alignment/=abs(alignment);pos=positive['events']['lepton'];pl=pos['charge_labels'];pr=np.array([a['joint'] for a in pos['records']]);order=[next(i for i,q in enumerate(pl) if abs(q+anti)<1e-10) for anti in labels];expected=pr[:,order,:,::-1]
    anti=dict(protocol='Independent direct anti insertion from SAME own fresh reference, opposite Pi-only field impulse, full ALL total-M H propagation, same-state nonstationary baseline.',initial_energy_variance_norm=norm(h@initial-phase*initial),initial_matter_changes={key:after[key]-before[key] for key in ['rho0','rho1','N','Q','C','B','phi2']},initial_current_changes=[mean(kicked,a)-mean(initial,a) for a in curr],records=records,charge_labels=labels,frozen_all_transverse_EM_off_excess={key:fxm[key]-fbm[key] for key in fbm},frozen_probe_current_image_norms=[norm(assemble(model,name,derivative=(mu,),coupled=False)@initial) for mu in range(6)],all_hops_off=dict(material_charge_motion_norm=norm(1j*(hopoff@(rho@initial)-rho@(hopoff@initial))),charge_baseline_TV_from_initial=float(np.sum(abs(qb-q0))/2),charge_pulse_TV_from_initial=float(np.sum(abs(qx-q0))/2),mechanical_current_image_norms=[norm(mechanical_operator(model,name,derivative=(mu,))@initial) for mu in range(6)],laboratory_density_excess=cj(np.vdot(hx,rhok@hx)-np.vdot(hb,rhok@hb))),material_graph_Ward=norm(graph),spatial_Fourier_Ward=norm(ward),wrong_no_mechanical_Fourier_Ward=norm(bad),physical_current_vs_Pi_force_defect=norm(force-curr[2]@initial),bare_projected_Pi_squared_cut_force=norm(bare),actual_C=dict(initial_phase_aligned_defect=norm(alignment*initial-c@pi),kick_defect=norm(alignment*kicked-c@pk),independent_all_M_event_defects=[norm(alignment*x-c@y) for x,y in zip(xs,px)],baseline_C_defects=[norm(alignment*x-c@y) for x,y in zip(bs,pb)],inclusive_reversed_charge_field_TV=[float(np.sum(abs(a-b))/2) for a,b in zip(receivers,expected)]))
