    out.write_text(json.dumps(result,indent=2)+'\n');np.savez_compressed(out.with_suffix('.npz'),antilepton_initial=initial,antilepton_kicked=kicked,antilepton_event=np.array(xs),antilepton_baseline=np.array(bs));print(json.dumps(result['resource']))


